/bin/zsh -lc "node - <<'NODE'
const fs=require('fs');
for(const kind of ['software-network','paged-gpu']){
 const d='target/evidence/e9-t24-exact-capstone-v2/'+kind;
 const source=JSON.parse(fs.readFileSync(d+'/report.json'));
 const saved=JSON.parse(fs.readFileSync(d+'/saved/storage.json'));
 const id=kind==='software-network'?source.result.sessionId:source.recording.id;
 const row=saved.stores.sessions.find(x=>x.key===id);
 const manifest=JSON.parse(Buffer.from(row.value.manifest));
 const mid=manifest.checkpoints[Math.max(0,Math.floor(manifest.checkpoints.length/2))];
 console.log(JSON.stringify({kind,id,checkpointCount:manifest.checkpoints.length,begin:manifest.begin,mid,end:manifest.end,sourceEnd:kind==='software-network'?source.result.final:source.recording.end},null,2));
}
NODE
nl -ba web/session-timeline.js | sed -n '1,240p'; nl -ba web/session-seek.js | sed -n '1,100p'; nl -ba web/session-gpu-replay.js | sed -n '1,100p'; nl -ba web/node_modules/playwright-core/lib/server/isomorphic/utilityScriptSerializers.js | sed -n '150,210p'"
